import copy, re, difflib
from docx.oxml.ns import qn
from lxml import etree

AUTHOR = "Ashford Blake LLP"
DATE = "2026-10-16T09:00:00Z"
_id = [9000]
def nid():
    _id[0] += 1
    return str(_id[0])

W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
XML_SPACE = "{http://www.w3.org/XML/1998/namespace}space"

def mk(tag, **attrs):
    e = etree.Element(qn(tag))
    for k, v in attrs.items():
        e.set(qn(k), v)
    return e

def track(tag):
    e = mk(tag)
    e.set(qn("w:id"), nid()); e.set(qn("w:author"), AUTHOR); e.set(qn("w:date"), DATE)
    return e

def run_text(r):
    s = ""
    for c in r:
        if c.tag == qn("w:t"): s += c.text or ""
        elif c.tag == qn("w:tab"): s += "\t"
    return s

def live_runs(p):
    return [c for c in p if c.tag == qn("w:r")]

def live_text(p):
    return "".join(run_text(r) for r in live_runs(p))

def accepted_text(p):
    out = ""
    for c in p.iter():
        if c.tag == qn("w:t"):
            out += c.text or ""
    return out

def _set_t(r, text):
    ts = [c for c in r if c.tag == qn("w:t")]
    for t in ts[1:]:
        r.remove(t)
    t = ts[0]
    t.text = text
    t.set(XML_SPACE, "preserve")

def _boundary(p, pos):
    """ensure a run boundary at char pos; return the run starting at pos or None"""
    off = 0
    for r in live_runs(p):
        t = run_text(r)
        L = len(t)
        if L == 0:
            continue
        if off == pos:
            return r
        if off < pos < off + L:
            k = pos - off
            new = copy.deepcopy(r)
            _set_t(r, t[:k]); _set_t(new, t[k:])
            r.addnext(new)
            return new
        off += L
    return None

def _runs_in(p, s, e):
    res = []; off = 0
    for r in live_runs(p):
        L = len(run_text(r))
        if L and off >= s and off + L <= e:
            res.append(r)
        off += L
    return res

def _rpr_at(p, pos):
    off = 0; last = None
    for r in live_runs(p):
        L = len(run_text(r))
        if L == 0: continue
        last = r
        if off <= pos < off + L:
            return r.find(qn("w:rPr"))
        off += L
    return last.find(qn("w:rPr")) if last is not None else None

def _new_run(text, rpr=None, fmt=None):
    r = mk("w:r")
    if rpr is not None:
        rp = copy.deepcopy(rpr)
    else:
        rp = base_rpr()
    if fmt:
        apply_fmt(rp, fmt)
    r.append(rp)
    t = mk("w:t"); t.text = text; t.set(XML_SPACE, "preserve")
    r.append(t)
    return r

def base_rpr():
    rp = mk("w:rPr")
    f = mk("w:rFonts"); f.set(qn("w:ascii"), "Times New Roman"); f.set(qn("w:hAnsi"), "Times New Roman"); rp.append(f)
    c = mk("w:color"); c.set(qn("w:val"), "000000"); rp.append(c)
    s = mk("w:sz"); s.set(qn("w:val"), "22"); rp.append(s)
    return rp

ORDER = ["rStyle","rFonts","b","bCs","i","iCs","caps","smallCaps","strike","dstrike","outline","shadow","emboss","imprint","noProof","snapToGrid","vanish","webHidden","color","spacing","w","kern","position","sz","szCs","highlight","u","effect","bdr","shd","fitText","vertAlign","rtl","cs","em","lang","eastAsianLayout","specVanish","oMath"]
def apply_fmt(rp, fmt):
    for k, v in fmt.items():
        tag = {"b":"b","i":"i","u":"u","hl":"highlight","sz":"sz"}[k]
        old = rp.find(qn("w:"+tag))
        if old is not None: rp.remove(old)
        if v is False or v is None: continue
        e = mk("w:"+tag)
        if tag == "u": e.set(qn("w:val"), "single")
        if tag == "highlight": e.set(qn("w:val"), v)
        if tag == "sz": e.set(qn("w:val"), str(v))
        rp.append(e)
    kids = list(rp)
    kids.sort(key=lambda e: ORDER.index(etree.QName(e).localname) if etree.QName(e).localname in ORDER else 99)
    for k in kids: rp.remove(k)
    for k in kids: rp.append(k)

def _del_runs(runs):
    dels = []
    for r in runs:
        d = track("w:del")
        r.addprevious(d); d.append(r)
        for t in r.findall(qn("w:t")):
            t.tag = qn("w:delText")
        dels.append(d)
    return dels

def _insert(p, pos, text, rpr, after=None, fmt=None):
    ins = track("w:ins")
    ins.append(_new_run(text, rpr, fmt))
    if after is not None:
        after.addnext(ins)
    else:
        r = _boundary(p, pos)
        if r is not None:
            # place before any del wrappers immediately preceding? just before run
            r.addprevious(ins)
        else:
            p.append(ins)
    return ins

TOK = re.compile(r"\s+|[A-Za-z0-9⅓⅔$%.,]+|[^\sA-Za-z0-9]")
def toks(s):
    return TOK.findall(s)

class EditError(Exception): pass

def edit(p, old, new, nth=0, whole=False, fmt=None):
    T = live_text(p)
    if T.count(old) == 0:
        raise EditError("NOT FOUND in para: %r\n  PARA: %r" % (old, T[:200]))
    base = -1
    for _ in range(nth + 1):
        base = T.find(old, base + 1)
    if whole:
        ops = [("replace", 0, 1, 0, 1)]; a = [old]; b = [new]
    else:
        a = toks(old); b = toks(new)
        sm = difflib.SequenceMatcher(None, a, b, autojunk=False)
        ops = [o for o in sm.get_opcodes() if o[0] != "equal"]
        # merge ops separated only by single whitespace equal tokens for readability
    cum = [0]
    for t in a: cum.append(cum[-1] + len(t))
    for tag, i1, i2, j1, j2 in reversed(ops):
        s = base + cum[i1]; e = base + cum[i2]
        ntext = "".join(b[j1:j2])
        if tag in ("replace", "delete"):
            rpr = _rpr_at(p, s)
            rpr = copy.deepcopy(rpr) if rpr is not None else None
            _boundary(p, s); _boundary(p, e)
            runs = _runs_in(p, s, e)
            dels = _del_runs(runs)
            if tag == "replace" and ntext:
                _insert(p, s, ntext, rpr, after=dels[-1] if dels else None, fmt=fmt)
        elif tag == "insert":
            rpr = _rpr_at(p, s - 1 if s > 0 else 0)
            rpr = copy.deepcopy(rpr) if rpr is not None else None
            # insert after the run ending at s
            _boundary(p, s)
            prev_end = None; off = 0
            for r in live_runs(p):
                L = len(run_text(r))
                if L == 0: continue
                off += L
                if off == s:
                    prev_end = r; break
            if prev_end is not None:
                # skip over following del wrappers so ins comes after them? keep right after run
                _insert(p, s, ntext, rpr, after=prev_end, fmt=fmt)
            else:
                _insert(p, s, ntext, rpr, fmt=fmt)
    return p

def edit_all(p, old, new):
    n = 0
    while old in live_text(p):
        edit(p, old, new); n += 1
        if n > 50: break
    return n

def mark_para_ins(p):
    pPr = p.find(qn("w:pPr"))
    if pPr is None:
        pPr = mk("w:pPr"); p.insert(0, pPr)
    rPr = pPr.find(qn("w:rPr"))
    if rPr is None:
        rPr = mk("w:rPr"); pPr.append(rPr)
    rPr.insert(0, track("w:ins"))

def delete_para(p):
    runs = [r for r in live_runs(p) if run_text(r)]
    _del_runs(runs)
    pPr = p.find(qn("w:pPr"))
    if pPr is None:
        pPr = mk("w:pPr"); p.insert(0, pPr)
    rPr = pPr.find(qn("w:rPr"))
    if rPr is None:
        rPr = mk("w:rPr"); pPr.append(rPr)
    rPr.append(track("w:del"))

def new_para(anchor, segs, tmpl=None, before=False, ppr=None):
    """segs: list of (text, fmt). tmpl: paragraph whose pPr is copied."""
    p = mk("w:p")
    src = ppr if ppr is not None else (tmpl.find(qn("w:pPr")) if tmpl is not None else None)
    if src is not None:
        pPr = copy.deepcopy(src)
        for x in pPr.findall(qn("w:rPr")): pPr.remove(x)
        p.append(pPr)
    mark_para_ins(p)
    ins = track("w:ins")
    for text, fmt in segs:
        if text == "\f":
            r = mk("w:r"); br = mk("w:br"); br.set(qn("w:type"), "page"); r.append(br); ins.append(r)
        else:
            ins.append(_new_run(text, None, fmt))
    p.append(ins)
    if before: anchor.addprevious(p)
    else: anchor.addnext(p)
    return p

# ---- tables
def tc_paras(tc):
    return tc.findall(qn("w:p"))

def cell_edit(cell, old, new, whole=False):
    for p in tc_paras(cell._tc):
        if old in live_text(p):
            return edit(p, old, new, whole=whole)
    raise EditError("cell text not found %r in %r" % (old, cell.text))

def delete_row(tr):
    trPr = tr.find(qn("w:trPr"))
    if trPr is None:
        trPr = mk("w:trPr")
        tblPrEx = tr.find(qn("w:tblPrEx"))
        if tblPrEx is not None: tblPrEx.addnext(trPr)
        else: tr.insert(0, trPr)
    trPr.append(track("w:del"))
    for p in tr.iter(qn("w:p")):
        delete_para(p)

def insert_row_after(tr, texts, tmpl_tr=None):
    src = tmpl_tr if tmpl_tr is not None else tr
    new = copy.deepcopy(src)
    trPr = new.find(qn("w:trPr"))
    if trPr is None:
        trPr = mk("w:trPr")
        tblPrEx = new.find(qn("w:tblPrEx"))
        if tblPrEx is not None: tblPrEx.addnext(trPr)
        else: new.insert(0, trPr)
    for x in trPr.findall(qn("w:del")) + trPr.findall(qn("w:ins")): trPr.remove(x)
    trPr.append(track("w:ins"))
    tcs = new.findall(qn("w:tc"))
    for tc, text in zip(tcs, texts):
        ps = tc.findall(qn("w:p"))
        for extra in ps[1:]: tc.remove(extra)
        p = ps[0]
        runs = [c for c in p.iter(qn("w:r"))]
        rpr = None
        for r in runs:
            if r.find(qn("w:rPr")) is not None:
                rpr = copy.deepcopy(r.find(qn("w:rPr"))); break
        for c in list(p):
            if c.tag != qn("w:pPr"): p.remove(c)
        pPr = p.find(qn("w:pPr"))
        if pPr is not None:
            for x in pPr.findall(qn("w:rPr")): pPr.remove(x)
        mark_para_ins(p)
        ins = track("w:ins"); ins.append(_new_run(text, rpr)); p.append(ins)
    tr.addnext(new)
    return new
